import{_ as e,o,c as t,a2 as l}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-07-20/teb_local_planner_cover.png",r="/Nav2ArticlesSite/article-assets/2026-07-20/teb_local_planner_01_architecture.png",c="/Nav2ArticlesSite/article-assets/2026-07-20/teb_local_planner_02_lifecycle.png",d="/Nav2ArticlesSite/article-assets/2026-07-20/teb_local_planner_03_interfaces.png",n="/Nav2ArticlesSite/article-assets/2026-07-20/teb_local_planner_04_control_cycle.png",h="/Nav2ArticlesSite/article-assets/2026-07-20/teb_local_planner_05_optimization_graph.png",s="/Nav2ArticlesSite/article-assets/2026-07-20/teb_local_planner_06_states_outcomes.png",v=JSON.parse('{"title":"局部路径为什么会“变形”？拆解 TEB 如何把空间、时间和避障压进一张优化图","description":"TEB 的全称是 Timed Elastic Band，直译是“带时间信息的弹性带”。它接收全局路径作为参考，把机器人未来一小段运动表示成一串二维位姿和相邻位姿之间的时间间隔，再同时优化路径形状与运动时间。","frontmatter":{"title":"局部路径为什么会“变形”？拆解 TEB 如何把空间、时间和避障压进一张优化图","description":"TEB 的全称是 Timed Elastic Band，直译是“带时间信息的弹性带”。它接收全局路径作为参考，把机器人未来一小段运动表示成一串二维位姿和相邻位姿之间的时间间隔，再同时优化路径形状与运动时间。","date":"2026-07-20","topic":"Nav2 工程实践","section":"二 · 全局规划与路径搜索","readingTime":12,"source":"2026-07-20/teb_local_planner_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-20/teb_local_planner_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/teb-local-planner-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"局部路径为什么会“变形”？拆解 TEB 如何把空间、时间和避障压进一张优化图"}],["meta",{"property":"og:description","content":"TEB 的全称是 Timed Elastic Band，直译是“带时间信息的弹性带”。它接收全局路径作为参考，把机器人未来一小段运动表示成一串二维位姿和相邻位姿之间的时间间隔，再同时优化路径形状与运动时间。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/teb-local-planner-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-20/teb_local_planner_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-20"}],["meta",{"name":"twitter:title","content":"局部路径为什么会“变形”？拆解 TEB 如何把空间、时间和避障压进一张优化图"}],["meta",{"name":"twitter:description","content":"TEB 的全称是 Timed Elastic Band，直译是“带时间信息的弹性带”。它接收全局路径作为参考，把机器人未来一小段运动表示成一串二维位姿和相邻位姿之间的时间间隔，再同时优化路径形状与运动时间。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-20/teb_local_planner_cover.png"}]],"prev":{"text":"栅格只能横平竖直？拆解 Theta* 如何用视线检查走出任意角全局路径","link":"/nav2/nav2-theta-star-planner-full-dataflow"},"next":{"text":"路径贴墙，真是规划器的锅吗？先调好 Costmap，再对决 NavFn A* 与 Smac2D","link":"/nav2/nav2-costmap-first-navfn-smac2d-tuning"}},"headers":[],"relativePath":"nav2/teb-local-planner-full-dataflow.md","filePath":"nav2/teb-local-planner-full-dataflow.md","lastUpdated":null}'),p={name:"nav2/teb-local-planner-full-dataflow.md"};function _(m,a,u,b,q,f){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="局部路径为什么会-变形-拆解-teb-如何把空间、时间和避障压进一张优化图" tabindex="-1">局部路径为什么会“变形”？拆解 TEB 如何把空间、时间和避障压进一张优化图 <a class="header-anchor" href="#局部路径为什么会-变形-拆解-teb-如何把空间、时间和避障压进一张优化图" aria-label="Permalink to &quot;局部路径为什么会“变形”？拆解 TEB 如何把空间、时间和避障压进一张优化图&quot;">​</a></h1><blockquote><p>本文基于当前项目中的 <code>teb_local_planner</code> ROS 2/Nav2 移植源码，梳理插件装载、生命周期、全局路径裁剪、障碍提取、时空轨迹优化、可行性复核、速度输出、恢复状态与可视化数据流。</p></blockquote><p><img src="'+i+'" alt="封面：TEB 时空轨迹优化"></p><h2 id="一、先给结论-teb-输出的不是-另一条全局路径" tabindex="-1">一、先给结论：TEB 输出的不是“另一条全局路径” <a class="header-anchor" href="#一、先给结论-teb-输出的不是-另一条全局路径" aria-label="Permalink to &quot;一、先给结论：TEB 输出的不是“另一条全局路径”&quot;">​</a></h2><p>TEB 的全称是 Timed Elastic Band，直译是“带时间信息的弹性带”。它接收全局路径作为参考，把机器人未来一小段运动表示成一串二维位姿和相邻位姿之间的时间间隔，再同时优化路径形状与运动时间。</p><p>在 Nav2 中，它是 <code>nav2_core::Controller</code> 插件，不是独立导航节点。直接输出是当前控制周期的 <code>geometry_msgs::msg::TwistStamped</code>；局部轨迹、候选拓扑和障碍物只是优化中间结果与可视化数据。</p><p>它要同时回答四件事：</p><ul><li>往哪里走：跟随全局路径和 via points。</li><li>怎样绕开障碍：把局部 Costmap 的致命栅格转成障碍点。</li><li>怎样符合底盘：约束速度、加速度、非完整运动学和最小转弯半径。</li><li>这一周期发什么速度：从优化轨迹前若干个位姿和时间差计算 <code>vx</code>、<code>vy</code>、<code>omega</code>。</li></ul><p><img src="'+r+'" alt="图 1：TEB 在 Nav2 控制链中的位置"></p><h2 id="二、谁调用它-controllerserver-才是-ros-接口外壳" tabindex="-1">二、谁调用它：ControllerServer 才是 ROS 接口外壳 <a class="header-anchor" href="#二、谁调用它-controllerserver-才是-ros-接口外壳" aria-label="Permalink to &quot;二、谁调用它：ControllerServer 才是 ROS 接口外壳&quot;">​</a></h2><p>插件 XML 导出 C++ 类型 <code>teb_local_planner::TebLocalPlannerROS</code>，基类为 <code>nav2_core::Controller</code>。<code>ControllerServer</code> 负责 FollowPath Action、控制频率、机器人位姿、速度、目标检查器和最终速度发布，TEB 只实现控制器插件约定。</p><p>五个直接入口构成完整调用面：</p><ul><li><code>configure()</code>：接收生命周期父节点、插件 ID、TF Buffer 和局部 Costmap。</li><li><code>setPlan()</code>：缓存新的全局 <code>Path</code>，但不立即清空已有 TEB，以便下一周期热启动。</li><li><code>computeVelocityCommands()</code>：每个控制周期完成全部局部规划和速度求解。</li><li><code>setSpeedLimit()</code>：接收 Costmap 速度限制信息。</li><li><code>activate()</code>、<code>deactivate()</code>、<code>cleanup()</code>：跟随 ControllerServer 生命周期管理可视化发布器。</li></ul><p>上层传给 <code>computeVelocityCommands()</code> 的输入包括机器人位姿、当前速度和 <code>GoalChecker</code>；返回的 <code>TwistStamped</code> 由 ControllerServer 继续经过进度检查、速度阈值和发布链路。</p><h2 id="三、生命周期与内部资源" tabindex="-1">三、生命周期与内部资源 <a class="header-anchor" href="#三、生命周期与内部资源" aria-label="Permalink to &quot;三、生命周期与内部资源&quot;">​</a></h2><p><code>configure()</code> 内部先调用只允许执行一次的 <code>initialize()</code>，完成核心资源初始化。</p><h3 id="_3-1-声明并加载参数" tabindex="-1">3.1 声明并加载参数 <a class="header-anchor" href="#_3-1-声明并加载参数" aria-label="Permalink to &quot;3.1 声明并加载参数&quot;">​</a></h3><p>声明并加载 TEB 参数。</p><h3 id="_3-2-准备障碍容器" tabindex="-1">3.2 准备障碍容器 <a class="header-anchor" href="#_3-2-准备障碍容器" aria-label="Permalink to &quot;3.2 准备障碍容器&quot;">​</a></h3><p>为障碍容器预留空间。</p><h3 id="_3-3-选择规划器" tabindex="-1">3.3 选择规划器 <a class="header-anchor" href="#_3-3-选择规划器" aria-label="Permalink to &quot;3.3 选择规划器&quot;">​</a></h3><p>根据 <code>enable_homotopy_class_planning</code> 选择单轨迹 <code>TebOptimalPlanner</code>，或多拓扑 <code>HomotopyClassPlanner</code>。</p><h3 id="_3-4-获取地图与机器人模型" tabindex="-1">3.4 获取地图与机器人模型 <a class="header-anchor" href="#_3-4-获取地图与机器人模型" aria-label="Permalink to &quot;3.4 获取地图与机器人模型&quot;">​</a></h3><p>获得局部 Costmap 和机器人 footprint。</p><h3 id="_3-5-创建轨迹可行性检查器" tabindex="-1">3.5 创建轨迹可行性检查器 <a class="header-anchor" href="#_3-5-创建轨迹可行性检查器" aria-label="Permalink to &quot;3.5 创建轨迹可行性检查器&quot;">​</a></h3><p>创建基于 DWB <code>ObstacleFootprintCritic</code> 的轨迹可行性检查器。</p><h3 id="_3-6-注册运行期接口" tabindex="-1">3.6 注册运行期接口 <a class="header-anchor" href="#_3-6-注册运行期接口" aria-label="Permalink to &quot;3.6 注册运行期接口&quot;">​</a></h3><p>注册动态参数回调和 <code>via_points</code> 订阅。</p><h3 id="_3-7-初始化恢复状态" tabindex="-1">3.7 初始化恢复状态 <a class="header-anchor" href="#_3-7-初始化恢复状态" aria-label="Permalink to &quot;3.7 初始化恢复状态&quot;">​</a></h3><p>初始化振荡检测窗口和恢复计时器。</p><p><code>initialize()</code> 返回后，<code>configure()</code> 再创建可视化对象，并配置五个生命周期发布器。</p><p>激活时五个发布器进入 Active；停用时全部 Deactivate；清理时调用可视化对象的 <code>on_cleanup()</code>。</p><p><img src="'+c+'" alt="图 2：生命周期、规划器选择与资源状态"></p><p>当前实现的 <code>cleanup()</code> 没有把 <code>initialized_</code> 复位，也没有显式释放规划器、订阅、动态参数句柄和可视化对象。因此“清理后再次配置”并不是一条完整重建路径，这是该移植版本需要补齐的生命周期边界。</p><h2 id="四、全部输入输出-有直接接口-也有间接-ros-数据" tabindex="-1">四、全部输入输出：有直接接口，也有间接 ROS 数据 <a class="header-anchor" href="#四、全部输入输出-有直接接口-也有间接-ros-数据" aria-label="Permalink to &quot;四、全部输入输出：有直接接口，也有间接 ROS 数据&quot;">​</a></h2><h3 id="_4-1-直接输入" tabindex="-1">4.1 直接输入 <a class="header-anchor" href="#_4-1-直接输入" aria-label="Permalink to &quot;4.1 直接输入&quot;">​</a></h3><ul><li><code>setPlan()</code> 输入 <code>nav_msgs::msg::Path</code>，保存为 <code>global_plan_</code>。</li><li><code>computeVelocityCommands()</code> 输入 <code>PoseStamped</code>、<code>Twist</code> 和 <code>GoalChecker*</code>。</li><li><code>setSpeedLimit()</code> 输入绝对速度限制或百分比限制。</li><li>共享局部 Costmap 提供致命障碍栅格、地图范围、分辨率、footprint 和坐标系。</li><li>TF Buffer 负责全局路径坐标系与局部规划坐标系之间的变换。</li><li>参数决定轨迹采样、机器人约束、障碍距离、优化权重、同伦类别和恢复行为。</li></ul><h3 id="_4-2-直接输出" tabindex="-1">4.2 直接输出 <a class="header-anchor" href="#_4-2-直接输出" aria-label="Permalink to &quot;4.2 直接输出&quot;">​</a></h3><ul><li><code>TwistStamped</code>：当前周期的底盘速度命令。</li><li>异常：变换失败、空局部路径、优化失败、发散、不可行或速度无效时抛出运行时错误，由 ControllerServer 处理。</li></ul><h3 id="_4-3-ros-订阅与可视化输出" tabindex="-1">4.3 ROS 订阅与可视化输出 <a class="header-anchor" href="#_4-3-ros-订阅与可视化输出" aria-label="Permalink to &quot;4.3 ROS 订阅与可视化输出&quot;">​</a></h3><p>插件自己还订阅相对名称 <code>via_points</code>，消息类型为 <code>nav_msgs::msg::Path</code>。可视化对象发布相对名称 <code>global_plan</code>、<code>local_plan</code>、<code>teb_poses</code>、<code>teb_markers</code> 和 <code>teb_feedback</code>；最终解析后的完整名称取决于 ControllerServer 所在命名空间。</p><p><img src="'+d+'" alt="图 3：TEB 的输入、输出、订阅与可视化接口"></p><h3 id="_4-4-当前障碍输入边界" tabindex="-1">4.4 当前障碍输入边界 <a class="header-anchor" href="#_4-4-当前障碍输入边界" aria-label="Permalink to &quot;4.4 当前障碍输入边界&quot;">​</a></h3><p>当前代码中的 costmap converter 和自定义障碍回调整段被注释，实际障碍输入只来自 Costmap 致命栅格；配置文件中即使保留 converter 参数，也不会形成动态多边形障碍数据流。</p><h2 id="五、一个控制周期的完整数据流" tabindex="-1">五、一个控制周期的完整数据流 <a class="header-anchor" href="#五、一个控制周期的完整数据流" aria-label="Permalink to &quot;五、一个控制周期的完整数据流&quot;">​</a></h2><p><code>computeVelocityCommands()</code> 是整个包的总入口。一周期按下面顺序执行。</p><h3 id="_5-1-初始化速度输出" tabindex="-1">5.1 初始化速度输出 <a class="header-anchor" href="#_5-1-初始化速度输出" aria-label="Permalink to &quot;5.1 初始化速度输出&quot;">​</a></h3><p>生成以 base frame 为坐标系、初值为零的 <code>TwistStamped</code>。</p><h3 id="_5-2-更新目标容差" tabindex="-1">5.2 更新目标容差 <a class="header-anchor" href="#_5-2-更新目标容差" aria-label="Permalink to &quot;5.2 更新目标容差&quot;">​</a></h3><p>从 <code>GoalChecker</code> 读取容差，并更新 TEB 的平面目标容差。</p><h3 id="_5-3-保存机器人状态" tabindex="-1">5.3 保存机器人状态 <a class="header-anchor" href="#_5-3-保存机器人状态" aria-label="Permalink to &quot;5.3 保存机器人状态&quot;">​</a></h3><p>保存当前机器人位姿和速度。</p><h3 id="_5-4-裁剪全局路径" tabindex="-1">5.4 裁剪全局路径 <a class="header-anchor" href="#_5-4-裁剪全局路径" aria-label="Permalink to &quot;5.4 裁剪全局路径&quot;">​</a></h3><p>从缓存全局路径中裁掉机器人身后的旧点。</p><h3 id="_5-5-变换局部路径" tabindex="-1">5.5 变换局部路径 <a class="header-anchor" href="#_5-5-变换局部路径" aria-label="Permalink to &quot;5.5 变换局部路径&quot;">​</a></h3><p>用 TF 将局部窗口内的全局路径变换到局部 Costmap 全局坐标系。</p><h3 id="_5-6-准备-via-points" tabindex="-1">5.6 准备 Via Points <a class="header-anchor" href="#_5-6-准备-via-points" aria-label="Permalink to &quot;5.6 准备 Via Points&quot;">​</a></h3><p>从局部路径自动抽取 via points，或使用外部 <code>via_points</code>。</p><h3 id="_5-7-更新恢复模式" tabindex="-1">5.7 更新恢复模式 <a class="header-anchor" href="#_5-7-更新恢复模式" aria-label="Permalink to &quot;5.7 更新恢复模式&quot;">​</a></h3><p>根据连续不可行次数和振荡检测进入恢复模式。</p><h3 id="_5-8-更新局部目标姿态" tabindex="-1">5.8 更新局部目标姿态 <a class="header-anchor" href="#_5-8-更新局部目标姿态" aria-label="Permalink to &quot;5.8 更新局部目标姿态&quot;">​</a></h3><p>用局部终点估计目标方向，并把局部路径首点替换为机器人真实位姿。</p><h3 id="_5-9-构造障碍对象" tabindex="-1">5.9 构造障碍对象 <a class="header-anchor" href="#_5-9-构造障碍对象" aria-label="Permalink to &quot;5.9 构造障碍对象&quot;">​</a></h3><p>扫描局部 Costmap，将致命障碍栅格转成点障碍。</p><h3 id="_5-10-优化-teb" tabindex="-1">5.10 优化 TEB <a class="header-anchor" href="#_5-10-优化-teb" aria-label="Permalink to &quot;5.10 优化 TEB&quot;">​</a></h3><p>锁住参数，初始化或热启动 TEB，构图并迭代优化。</p><h3 id="_5-11-检查轨迹可行性" tabindex="-1">5.11 检查轨迹可行性 <a class="header-anchor" href="#_5-11-检查轨迹可行性" aria-label="Permalink to &quot;5.11 检查轨迹可行性&quot;">​</a></h3><p>检查优化发散和 footprint 碰撞可行性。</p><h3 id="_5-12-提取并限制速度" tabindex="-1">5.12 提取并限制速度 <a class="header-anchor" href="#_5-12-提取并限制速度" aria-label="Permalink to &quot;5.12 提取并限制速度&quot;">​</a></h3><p>从轨迹前若干点提取速度，执行限幅；车式底盘可把角速度换成转角。</p><h3 id="_5-13-发布结果" tabindex="-1">5.13 发布结果 <a class="header-anchor" href="#_5-13-发布结果" aria-label="Permalink to &quot;5.13 发布结果&quot;">​</a></h3><p>更新恢复状态，发布调试可视化，返回速度命令。</p><p><img src="'+n+'" alt="图 4：控制命令计算的单周期流水线"></p><h2 id="六、全局路径怎样变成局部参考路径" tabindex="-1">六、全局路径怎样变成局部参考路径 <a class="header-anchor" href="#六、全局路径怎样变成局部参考路径" aria-label="Permalink to &quot;六、全局路径怎样变成局部参考路径&quot;">​</a></h2><p><code>setPlan()</code> 会逐个复制全局 Path 的 pose，并统一使用 Path header。它刻意不清空已有局部规划器，因为全局规划器可能频繁刷新路径；TEB 希望下一控制周期复用旧轨迹做热启动。</p><p>进入控制周期后，<code>pruneGlobalPlan()</code> 先把机器人位姿变换到路径坐标系，并删除机器人身后一段路径。随后 <code>transformGlobalPlan()</code> 执行以下步骤。</p><h3 id="_6-1-获取坐标变换" tabindex="-1">6.1 获取坐标变换 <a class="header-anchor" href="#_6-1-获取坐标变换" aria-label="Permalink to &quot;6.1 获取坐标变换&quot;">​</a></h3><p>获取路径坐标系到局部规划坐标系的 TF。</p><h3 id="_6-2-查找局部最近点" tabindex="-1">6.2 查找局部最近点 <a class="header-anchor" href="#_6-2-查找局部最近点" aria-label="Permalink to &quot;6.2 查找局部最近点&quot;">​</a></h3><p>在路径上寻找机器人附近的局部最近点。</p><h3 id="_6-3-按-costmap-范围裁剪" tabindex="-1">6.3 按 Costmap 范围裁剪 <a class="header-anchor" href="#_6-3-按-costmap-范围裁剪" aria-label="Permalink to &quot;6.3 按 Costmap 范围裁剪&quot;">​</a></h3><p>只保留局部 Costmap 半径约 85％范围内的点。</p><h3 id="_6-4-限制累计前视距离" tabindex="-1">6.4 限制累计前视距离 <a class="header-anchor" href="#_6-4-限制累计前视距离" aria-label="Permalink to &quot;6.4 限制累计前视距离&quot;">​</a></h3><p>同时受 <code>max_global_plan_lookahead_dist</code> 累计长度限制。</p><h3 id="_6-5-补入全局终点" tabindex="-1">6.5 补入全局终点 <a class="header-anchor" href="#_6-5-补入全局终点" aria-label="Permalink to &quot;6.5 补入全局终点&quot;">​</a></h3><p>如果机器人已经非常接近全局终点、裁剪结果为空，则显式注入全局终点。</p><p>这里有一个确定的当前代码缺陷：函数在检查 <code>global_plan.empty()</code> 之前就访问 <code>global_plan[0]</code>。如果上层传入空路径，理论上的错误分支还没执行就已经发生越界访问。</p><h2 id="七、弹性带里到底存了什么" tabindex="-1">七、弹性带里到底存了什么 <a class="header-anchor" href="#七、弹性带里到底存了什么" aria-label="Permalink to &quot;七、弹性带里到底存了什么&quot;">​</a></h2><h3 id="_7-1-优化变量" tabindex="-1">7.1 优化变量 <a class="header-anchor" href="#_7-1-优化变量" aria-label="Permalink to &quot;7.1 优化变量&quot;">​</a></h3><p><code>TimedElasticBand</code> 的状态不是普通 Path，而是交替排列的两类优化变量：</p><ul><li><code>PoseSE2</code>：每个采样点的 <code>x</code>、<code>y</code>、<code>theta</code>。</li><li><code>TimeDiff</code>：相邻两个位姿之间的时间间隔 <code>Δt</code>。</li></ul><p>新任务第一次进入时，用裁剪后的全局路径初始化这些变量。如果新终点与旧终点距离和角度变化不大，就调用 <code>updateAndPruneTEB()</code>，删除已经走过的前段并更新起终点；变化过大才清空重建。</p><p>外循环先用 <code>dt_ref</code>、<code>dt_hysteresis</code>、最少和最多采样数自动调整轨迹离散密度，再构建 g2o 优化图。内循环使用 Levenberg-Marquardt 求解。每轮外循环还会用 <code>weight_adapt_factor</code> 逐步增强部分约束权重。</p><p><img src="'+h+'" alt="图 5：Pose、TimeDiff 与 g2o 约束图"></p><h3 id="_7-2-优化约束" tabindex="-1">7.2 优化约束 <a class="header-anchor" href="#_7-2-优化约束" aria-label="Permalink to &quot;7.2 优化约束&quot;">​</a></h3><p>优化图包含的主要边包括：</p><ul><li>障碍物与膨胀距离约束。</li><li>动态障碍约束，前提是实际障碍对象带速度；当前 Costmap 点障碍链路并不提供这一信息。</li><li>via point 贴合约束。</li><li>最大速度、最大加速度约束。</li><li>总时间最优与最短路径约束。</li><li>差速或车式运动学约束。</li><li>偏好转向方向约束。</li><li>速度与障碍距离比约束。</li></ul><p>因此，TEB 不是先算路径再独立做速度规划，而是在同一张图中共同调整空间位姿和时间间隔。</p><h2 id="八、单条-teb-与多同伦类别-teb" tabindex="-1">八、单条 TEB 与多同伦类别 TEB <a class="header-anchor" href="#八、单条-teb-与多同伦类别-teb" aria-label="Permalink to &quot;八、单条 TEB 与多同伦类别 TEB&quot;">​</a></h2><p>关闭 <code>enable_homotopy_class_planning</code> 时，只维护一个 <code>TebOptimalPlanner</code>。打开后，<code>HomotopyClassPlanner</code> 会探索绕障碍物左右两侧等不同拓扑类别，为每类初始化一条 TEB，并可并行优化。</p><p>多类别流程如下。</p><h3 id="_8-1-更新已有候选" tabindex="-1">8.1 更新已有候选 <a class="header-anchor" href="#_8-1-更新已有候选" aria-label="Permalink to &quot;8.1 更新已有候选&quot;">​</a></h3><p>更新并分析上周期保留下来的候选轨迹。</p><h3 id="_8-2-探索新等价类" tabindex="-1">8.2 探索新等价类 <a class="header-anchor" href="#_8-2-探索新等价类" aria-label="Permalink to &quot;8.2 探索新等价类&quot;">​</a></h3><p>根据图搜索结果探索新的等价类。</p><h3 id="_8-3-加入全局参考候选" tabindex="-1">8.3 加入全局参考候选 <a class="header-anchor" href="#_8-3-加入全局参考候选" aria-label="Permalink to &quot;8.3 加入全局参考候选&quot;">​</a></h3><p>将全局参考路径作为一个优先候选。</p><h3 id="_8-4-绑定-via-points" tabindex="-1">8.4 绑定 Via Points <a class="header-anchor" href="#_8-4-绑定-via-points" aria-label="Permalink to &quot;8.4 绑定 Via Points&quot;">​</a></h3><p>为各候选绑定 via points。</p><h3 id="_8-5-优化全部候选" tabindex="-1">8.5 优化全部候选 <a class="header-anchor" href="#_8-5-优化全部候选" aria-label="Permalink to &quot;8.5 优化全部候选&quot;">​</a></h3><p>串行或多线程优化所有候选。</p><h3 id="_8-6-选择最佳-teb" tabindex="-1">8.6 选择最佳 TEB <a class="header-anchor" href="#_8-6-选择最佳-teb" aria-label="Permalink to &quot;8.6 选择最佳 TEB&quot;">​</a></h3><p>根据总成本、障碍成本缩放、时间成本、上一最佳轨迹滞回和初始路径偏好选择最佳 TEB。</p><h3 id="_8-7-限制拓扑切换" tabindex="-1">8.7 限制拓扑切换 <a class="header-anchor" href="#_8-7-限制拓扑切换" aria-label="Permalink to &quot;8.7 限制拓扑切换&quot;">​</a></h3><p>在 <code>switching_blocking_period</code> 内限制频繁切换拓扑类别。</p><p>可行性检查如果发现最佳候选碰撞，会移除该候选并尝试下一个；如果不可行候选恰好是上周期最佳轨迹，则直接失败，避免轨迹之间来回振荡。</p><h2 id="九、从优化轨迹到速度命令" tabindex="-1">九、从优化轨迹到速度命令 <a class="header-anchor" href="#九、从优化轨迹到速度命令" aria-label="Permalink to &quot;九、从优化轨迹到速度命令&quot;">​</a></h2><p><code>getVelocityCommand()</code> 至少要求两个轨迹位姿。它从第一个位姿向前累计若干 <code>TimeDiff</code>，在配置的前视位姿范围内选定目标采样点，然后按底盘类型计算速度。</p><h3 id="_9-1-非全向底盘速度" tabindex="-1">9.1 非全向底盘速度 <a class="header-anchor" href="#_9-1-非全向底盘速度" aria-label="Permalink to &quot;9.1 非全向底盘速度&quot;">​</a></h3><p>沿机器人朝向投影得到 <code>vx</code>，<code>vy=0</code>。</p><h3 id="_9-2-全向底盘速度" tabindex="-1">9.2 全向底盘速度 <a class="header-anchor" href="#_9-2-全向底盘速度" aria-label="Permalink to &quot;9.2 全向底盘速度&quot;">​</a></h3><p>将位移旋转到机器人坐标系，得到 <code>vx</code> 和 <code>vy</code>。</p><h3 id="_9-3-角速度" tabindex="-1">9.3 角速度 <a class="header-anchor" href="#_9-3-角速度" aria-label="Permalink to &quot;9.3 角速度&quot;">​</a></h3><p>归一化后的方向差除以累计时间。</p><p>优化使用软约束，因此结果还要经过 <code>saturateVelocity()</code> 硬限幅。<code>use_proportional_saturation=true</code> 时，三个速度分量按同一最小比例缩放，尽量保持曲率；否则分别裁剪。</p><p>车式底盘打开 <code>cmd_angle_instead_rotvel</code> 后，使用轴距和转弯半径把角速度转换成转向角。如果结果不是有限数，整条轨迹会被清空，本周期失败。</p><h2 id="十、恢复机制不是-behavior-server-的恢复行为" tabindex="-1">十、恢复机制不是 Behavior Server 的恢复行为 <a class="header-anchor" href="#十、恢复机制不是-behavior-server-的恢复行为" aria-label="Permalink to &quot;十、恢复机制不是 Behavior Server 的恢复行为&quot;">​</a></h2><p>本包内部有两种局部恢复状态，它们发生在控制器内部，不是 Nav2 Behavior Server 的 spin、backup 或 wait。</p><h3 id="_10-1-缩短视野" tabindex="-1">10.1 缩短视野 <a class="header-anchor" href="#_10-1-缩短视野" aria-label="Permalink to &quot;10.1 缩短视野&quot;">​</a></h3><p>检测到不可行轨迹后，至少在 <code>shrink_horizon_min_duration</code> 内把局部目标向前收缩约 50％；连续失败超过 9 次时进一步缩短。</p><h3 id="_10-2-振荡恢复" tabindex="-1">10.2 振荡恢复 <a class="header-anchor" href="#_10-2-振荡恢复" aria-label="Permalink to &quot;10.2 振荡恢复&quot;">​</a></h3><p><code>FailureDetector</code> 根据一段时间内的线速度与角速度符号变化判断振荡，并把当前旋转方向设置为优化偏好，保持到恢复窗口过期。</p><p>成功得到可行速度后，连续不可行计数归零；规划失败、发散、碰撞或速度无效都会增加计数、记录时间、保存零速度并清空规划器。</p><p><img src="'+s+'" alt="图 6：成功、失败与局部恢复状态机"></p><h2 id="十一、当前移植源码需要特别留意的边界" tabindex="-1">十一、当前移植源码需要特别留意的边界 <a class="header-anchor" href="#十一、当前移植源码需要特别留意的边界" aria-label="Permalink to &quot;十一、当前移植源码需要特别留意的边界&quot;">​</a></h2><p>除空路径越界和生命周期清理不完整外，还有几处直接影响实车行为：</p><ul><li>动态 footprint 更新分支把新 footprint 反向覆盖为旧值，实际没有更新 <code>footprint_spec_</code>，也没有把新结果正确保存。</li><li><code>setSpeedLimit()</code> 只有前向 <code>max_vel_x</code> 被正确修改；后退、横向和角速度分支多处写入 <code>base_max_*</code> 自身，而不是活动上限 <code>max_vel_*</code>。百分比限制还会累计改写基准值。</li><li><code>customViaPointsCB()</code> 有互斥锁，但控制周期读取 <code>via_points_</code> 时没有使用同一把锁，存在并发访问边界。</li><li>Costmap 转障碍只采集 <code>LETHAL_OBSTACLE</code>，不会把膨胀层、未知区域或语义多边形直接变成障碍对象。</li><li>配置里存在 costmap converter 参数，但对应实现被注释；不能据此判断动态障碍预测已经接通。</li><li>轨迹优化时锁住参数配置，但动态参数回调、速度限制更新与其他容器的并发边界仍不完整。</li></ul><p>这些内容不等于 TEB 算法本身有问题，而是当前 ROS 2 移植版本的工程完成度边界。上线前应针对空路径、动态 footprint、速度限制、生命周期重配和并发 via points 建立回归测试。</p><h2 id="十二、调参应该按什么顺序" tabindex="-1">十二、调参应该按什么顺序 <a class="header-anchor" href="#十二、调参应该按什么顺序" aria-label="Permalink to &quot;十二、调参应该按什么顺序&quot;">​</a></h2><h3 id="_12-1-保证几何模型正确" tabindex="-1">12.1 保证几何模型正确 <a class="header-anchor" href="#_12-1-保证几何模型正确" aria-label="Permalink to &quot;12.1 保证几何模型正确&quot;">​</a></h3><p>先检查 footprint、<code>min_obstacle_dist</code>、局部 Costmap 分辨率和膨胀距离。</p><h3 id="_12-2-保证底盘约束正确" tabindex="-1">12.2 保证底盘约束正确 <a class="header-anchor" href="#_12-2-保证底盘约束正确" aria-label="Permalink to &quot;12.2 保证底盘约束正确&quot;">​</a></h3><p>再检查 <code>max_vel_*</code>、<code>acc_lim_*</code>、是否全向、最小转弯半径和轴距。</p><h3 id="_12-3-调整时间离散" tabindex="-1">12.3 调整时间离散 <a class="header-anchor" href="#_12-3-调整时间离散" aria-label="Permalink to &quot;12.3 调整时间离散&quot;">​</a></h3><p>调整 <code>dt_ref</code>、<code>dt_hysteresis</code>、<code>min_samples</code>、<code>max_samples</code> 和控制前视位姿数。</p><h3 id="_12-4-调整优化权重" tabindex="-1">12.4 调整优化权重 <a class="header-anchor" href="#_12-4-调整优化权重" aria-label="Permalink to &quot;12.4 调整优化权重&quot;">​</a></h3><p>随后调整速度、加速度、障碍、via point、最优时间和运动学权重。</p><h3 id="_12-5-启用多同伦类别和多线程" tabindex="-1">12.5 启用多同伦类别和多线程 <a class="header-anchor" href="#_12-5-启用多同伦类别和多线程" aria-label="Permalink to &quot;12.5 启用多同伦类别和多线程&quot;">​</a></h3><p>最后再打开多同伦类别和多线程。它能提升复杂绕障场景的选择能力，但也会显著增加计算量和调参维度。</p><p>调参时至少同时记录控制周期耗时、最小障碍距离、轨迹总时间、速度连续性、不可行次数和拓扑切换次数，只看 RViz 轨迹“顺不顺眼”远远不够。</p><h2 id="十三、结语" tabindex="-1">十三、结语 <a class="header-anchor" href="#十三、结语" aria-label="Permalink to &quot;十三、结语&quot;">​</a></h2><p>TEB 的价值，是把“路径长什么样”和“多快走过去”放到一个统一优化问题里。全局路径提供方向，局部 Costmap 提供障碍，机器人模型提供可执行边界，时间变量把几何路径变成速度命令。</p><p>真正读懂它，不是记住几十个权重，而是抓住一条主线：全局 Path 先被裁剪和变换，随后变成 Pose 与 TimeDiff 组成的弹性带，再通过约束图优化、footprint 可行性复核和速度限幅，最终在每个控制周期输出一条可执行命令。</p>',153)])])}const x=e(p,[["render",_]]);export{v as __pageData,x as default};
